graphql.query:
query Todos($status: NoteStatus, $limit: Int, $offset: Int) {
  todos(status: $status, limit: $limit, offset: $offset) {
    id
    title
    content
    items {
      id
      text
      isCompleted
    }
    backgroundImage
    status
    createdAt
    updatedAt
    userId
  }
}

mutation Login($email: String!, $password: String!) {
  login(email: $email, password: $password) {
    token
    refreshToken
    expiresIn
    user {
      id
      username
      email
      profileImage
      firstName
      secondName
      description
      lastLogin
      creationDate
      modifiedDate
    }
  }
}

mutation Refresh($refreshToken: String!) {
  refresh(refreshToken: $refreshToken) {
    token
    refreshToken
    expiresIn
  }
}

mutation Signup($email: String!, $password: String!) {
  signup(email: $email, password: $password) {
    message
    user {
      id
      username
      email
      profileImage
      firstName
      secondName
      description
      lastLogin
      creationDate
      modifiedDate
    }
  }
}

mutation UpdateAccount($input: UpdateAccountInput!) {
  updateAccount(input: $input) {
    message
    user {
      id
      username
      email
      profileImage
      firstName
      secondName
      description
      lastLogin
      creationDate
      modifiedDate
    }
    token
    refreshToken
    expiresIn
  }
}

